a, n = input().split()
a, n = int(a), int(n)
max_lucky = 1001 ** 2 + 10
is_lucky = [False for i in range(max_lucky + 1)]
next_lucky = [-1 for i in range(max_lucky + 1)]
for i in range(1, max_lucky):
    if i >= a and int(i ** 0.5) ** 2 == i:
        is_lucky[i] = True
        for j in range(i + i, max_lucky, i):
            is_lucky[j] = True
for i in range(max_lucky - 1, 0, -1):
    if is_lucky[i]:
        next_lucky[i] = i
    else:
        next_lucky[i] = next_lucky[i + 1]
for i in range(n):
    x = int(input())
    assert 1 <= x <= 10 ** 6 + 1
    if next_lucky[x] == x:
        print("lucky")
    else:
        print(next_lucky[x])

n = int(input())
a = list(map(int, input().split()))
a = [0] + a
def sort_(l, r, k):
    while l <= r:
        while (l <= r) and (a[l] >> k & 1):
            l += 1
        while (l <= r) and (not (a[r] >> k & 1)):
            r -= 1
        if l <= r:
            a[l], a[r] = a[r], a[l]
            l += 1
            r -= 1
    return r
ans = 0
for i in range(31, -1, -1):
    j = sort_(1, n, i)
    if j >= 2:
        ans |= 1 << i
        n = j
print(ans)
